View design (based on established conventions):

```vue
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'

import EmptyState from '@/components/common/EmptyState.vue'
import ErrorState from '@/components/common/ErrorState.vue'
import LoadingSkeleton from '@/components/common/LoadingSkeleton.vue'
import PageHeader from '@/components/common/PageHeader.vue'
import PageShell from '@/components/common/PageShell.vue'
import StatusBadge from '@/components/common/StatusBadge.vue'
import { ApiRequestError } from '@/api/client'
import { workflowsApi } from '@/api/workflows'
import { formatDateTime, formatDuration } from '@/utils/format'
import type { WorkflowRun } from '@/types'

const route = useRoute()
const router = useRouter()

const items = ref<WorkflowRun[]>([])
const loading = ref(true)
const loadingMore = ref(false)
const error = ref<string | null>(null)
/** Non-null when the error is a business error (not_found/forbidden), at which point a fixed message is shown and retry is hidden. */
const errorCode = ref<string | null>(null)
const nextCursor = ref<string | null>(null)
const hasMore = ref(false)

const workflowId = computed(() => String(route.params.id ?? ''))

const canLoadMore = computed(() => hasMore.value && nextCursor.value !== null)

/** run status → StatusBadge semantic tone (F3 plan values: succeeded→ok; running/failed→warn; canceled/interrupted→muted; unknown falls back to muted). */
const STATUS_TONES: Record<string, 'ok' | 'warn' | 'muted'> = {
  succeeded: 'ok',
  running: 'warn',
  failed: 'warn',
  canceled: 'muted',
  interrupted: 'muted',
}

const STATUS_LABELS: Record<string, string> = {
  queued: 'Queued',
  running: 'Running',
  succeeded: 'Succeeded',
  failed: 'Failed',
  canceled: 'Canceled',
  interrupted: 'Interrupted',
}

function statusTone(status: string): 'ok' | 'warn' | 'muted' {
  return STATUS_TONES[status] ?? 'muted'
}

function statusLabel(status: string | null): string {
  if (!status) return '—'
  return STATUS_LABELS[status] ?? status
}

/** Business errors (404/403) get fixed messages per the plan and are not retryable; other errors show the original message. */
function errorInfo(cause: unknown): { message: string; code: string | null } {
  if (cause instanceof ApiRequestError) {
    if (cause.code === 'not_found') return { message: 'Workflow not found', code: cause.code }
    if (cause.code === 'forbidden') return { message: 'Run history is only viewable by the template creator', code: cause.code }
    return { message: cause.message || 'Failed to load run history', code: cause.code }
  }
  return { message: cause instanceof Error ? cause.message : 'Failed to load run history', code: null }
}

async function load(): Promise<void> {
  loading.value = true
  error.value = null
  errorCode.value = null
  nextCursor.value = null
  hasMore.value = false
  try {
    const page = await workflowsApi.listRuns(workflowId.value)
    items.value = page.items
    nextCursor.value = page.next_cursor
    hasMore.value = page.has_more
  } catch (cause) {
    const info = errorInfo(cause)
    error.value = info.message
    errorCode.value = info.code
  } finally {
    loading.value = false
  }
}

/** Cursor pagination: use next_cursor to load and append. */
async function loadMore(): Promise<void> {
  if (loadingMore.value || !nextCursor.value) return
  loadingMore.value = true
  try {
    const page = await workflowsApi.listRuns(workflowId.value, { cursor: nextCursor.value })
    items.value = [...items.value, ...page.items]
    nextCursor.value = page.next_cursor
    hasMore.value = page.has_more
  } catch {
    ElMessage.error('Failed to load more')
  } finally {
    loadingMore.value = false
  }
}

async function copyRunId(run: WorkflowRun): Promise<void> {
  try {
    await navigator.clipboard.writeText(run.run_id)
    ElMessage.success('run_id copied')
  } catch {
    ElMessage.error('Copy failed, please select the content manually')
  }
}

onMounted(() => {
  void load()
})
</script>
```

Template:

```vue
<template>
